1026	  _parseQuery(query) {
1027	    var trimmed = query.trim()
1028	    if (!trimmed) return []
1029	    
1030	    var hashes = []
1031	    if (/^-?\d+$/.test(trimmed.replace(/\s/g, ''))) {
1032	      return []
1033	    }
1034	    
1035	    var words = trimmed.split(this.config.tokenizer.delimiters)
1036	    var minPrefix = this.config.tokenizer.minEnglishPrefix
1037	    
1038	    for (var i = 0; i < words.length; i++) {
1039	      var word = words[i]
1040	      if (word.length === 0) continue
1041	      if (/^[a-zA-Z]+$/.test(word)) {
1042	        if (word.length >= minPrefix) {
1043	          for (var j = minPrefix; j <= word.length; j++) {
1044	            hashes.push(hashCode(word.substring(0, j).toLowerCase()))
1045	          }
1046	        } else {
1047	          hashes.push(hashCode(word.toLowerCase()))
1048	        }
1049	      } else {
1050	        for (var k = 0; k < word.length; k++) {
1051	          var ch = word[k]
1052	          if (ch && ch.trim().length > 0) {
1053	            hashes.push(hashCode(ch))
1054	          }
1055	        }
1056	      }
1057	    }
1058	    
1059	    var unique = []
1060	    for (var m = 0; m < hashes.length; m++) {
1061	      if (unique.indexOf(hashes[m]) === -1) unique.push(hashes[m])
1062	    }
1063	    return unique
1064	  }
