1078	    
1079	    if (this.yearToIds[yearKey]) {
1080	      allIds = allIds.concat(this.yearToIds[yearKey])
1081	    }
1082	    
1083	    var offset = 1
1084	    var maxResults = this.config.search.yearMaxResults
1085	    var rangeLimit = this.config.search.yearRangeLimit
1086	    
1087	    while (allIds.length < maxResults && offset <= rangeLimit) {
1088	      var prevKey = (targetYear - offset).toString()
1089	      var nextKey = (targetYear + offset).toString()
1090	      if (this.yearToIds[prevKey]) {
1091	        allIds = allIds.concat(this.yearToIds[prevKey])
1092	      }
1093	      if (this.yearToIds[nextKey]) {
1094	        allIds = allIds.concat(this.yearToIds[nextKey])
1095	      }
1096	      offset++
1097	    }
1098	    
1099	    return allIds
