const fs = require('fs')
const path = require('path')

const targets = ['src/app.ux', 'src/pages/splash/splash.ux']
let failed = false

for (const rel of targets) {
  const abs = path.join(__dirname, rel)
  const content = fs.readFileSync(abs, 'utf8')
  const m = content.match(/<script>([\s\S]*?)<\/script>/)
  if (!m) {
    console.error(`[SKIP] no <script> in ${rel}`)
    continue
  }
  try {
    // 构造 ESM 模块会执行完整语法解析，语法错误会在此时抛出
    new (require('vm').SourceTextModule)(m[1])
    console.log(`[OK] ${rel} script syntax valid`)
  } catch (e) {
    failed = true
    console.error(`[FAIL] ${rel} -> ${e.message}`)
  }
}

process.exit(failed ? 1 : 0)

