124	          checkDone()
125	        },
126	        fail: function() {
127	          global.autoSearch = false
128	          checkDone()
129	        }
130	      })
131	
132	      storage.get({
133	        key: 'app_theme',
134	        success: function(data) { global.theme = data === 'dark' ? 'dark' : 'light'; checkDone() },
135	        fail: function() { global.theme = 'light'; checkDone() }
136	      })
137	
138	      storage.get({
139	        key: 'defaultCategory',
140	        success: function(data) { global.defaultCategory = data || 'all'; checkDone() },
141	        fail: function() { global.defaultCategory = 'all'; checkDone() }
142	      })
143	
144	      storage.get({
145	        key: 'defaultRegion',
146	        success: function(data) { global.defaultRegion = data || 'all'; checkDone() },
147	        fail: function() { global.defaultRegion = 'all'; checkDone() }
148	      })
149	
150	      storage.get({
151	        key: 'yearIndexCache',
152	        success: function() { checkDone() },
153	        fail: function() { checkDone() }
154	      })
155	
156	      storage.get({
157	        key: 'keywordIndexCache',
158	        success: function() { checkDone() },
