166	  // 加载名言数据（不阻塞）
167	  function loadQuotes() {
168	    var file = require('@system.file')
169	    file.readText({
170	      uri: '/common/quotes.txt',
171	      success: function(data) {
172	        var lines = data.text.split('\n')
173	        global.quotes = lines
174	          .filter(function(line) { return line.indexOf('|') !== -1 })
175	          .map(function(line) {
176	            var parts = line.split('|')
177	            return { text: parts[0], author: parts[1] }
178	          })
179	        global.addRuntimeLog('名言数据加载完成', 'success')
180	      },
181	      fail: function() {
182	        global.quotes = [{ text: '以史为镜，可以知兴替', author: '李世民' }]
183	        global.addRuntimeLog('名言数据加载失败，使用默认', 'warn')
184	      }
185	    })
186	  }
