188	  // 挂载全局接口（幂等，可在引擎就绪前后多次调用）
189	  function mountToGlobal() {
190	    var engine = engineInstance
191	    if (!engine) return
192	
193	    global.addRuntimeLog('挂载全局接口', 'info')
194	
195	    // mapChunkSize / detailChunkSize：meta 加载前取默认值，引擎就绪后再刷新
196	    global.mapChunkSize = engine.mapChunkSize || 100
197	    global.detailChunkSize = engine.detailChunkSize || 100
198	
199	    var regionMap = {
200	      'asia': '亚洲',
201	      'europe': '欧洲',
202	      'africa': '非洲',
203	      'north_america': '北美洲',
204	      'south_america': '南美洲',
205	      'other': '其他'
206	    }
207	
208	    global.searchHistory = async function(query, options) {
209	      options = options || {}
210	      var category = options.category !== undefined ? options.category : 'all'
211	      var region = options.region !== undefined ? options.region : 'all'
212	      var page = options.page || 1
213	      var pageSize = options.pageSize || 20
214	
215	      try {
216	        // ✅ 关键：await，SearchEngine.search 内部会判断 isReady
217	        var result = await engine.search(query, {
218	          category: category,
219	          region: region,
220	          page: page,
221	          pageSize: pageSize
222	        })
223	
224	        // 防御性检查
225	        if (!result || !result.results) {
226	          return { results: [], total: 0 }
227	        }
228	
229	        return {
230	          results: result.results.map(function(item) {
231	            var displayTitle = item.title
232	            if (!displayTitle || displayTitle === '') {
233	              displayTitle = item.yearDisplay + ' ' + (regionMap[item.region] || item.region)
234	            }
235	            return {
236	              _id: item.id,
237	              id: item.id,
238	              year: item.year,
239	              yearDisplay: item.yearDisplay,
240	              region: regionMap[item.region] || item.region,
241	              regionTag: item.region,
242	              category: item.category,
243	              title: displayTitle,
244	              keywords: [displayTitle],
245	              cause: item.cause || '',
246	              impact: item.impact || ''
247	            }
248	          }),
249	          total: result.total || 0
250	        }
251	      } catch(e) {
252	        console.error('[searchHistory] 错误:', e)
253	        return { results: [], total: 0 }
254	      }
255	    }
256	
257	    global.getItemById = async function(id) {
258	      var logs = []
259	      logs.push('[global.getItemById] id=' + id)
260	      try {
261	        var result = await engine.getDoc(id)
262	        if (result) {
263	          logs.push('success, title=' + result.title)
264	          global.addRuntimeLog(logs.join(' | '), 'success')
265	        } else {
266	          logs.push('result null')
267	          global.addRuntimeLog(logs.join(' | '), 'warn')
268	        }
269	        return result
270	      } catch(e) {
271	        logs.push('error: ' + e.message)
272	        global.addRuntimeLog(logs.join(' | '), 'error')
273	        return null
274	      }
275	    }
276	
277	    global.getItemByIdSync = function(id) {
278	      var doc = engine.getDocSync(id)
279	      if (!doc) return null
280	      var displayTitle = doc.title
281	      if (!displayTitle || displayTitle === '') {
282	        displayTitle = doc.yearDisplay + ' ' + (regionMap[doc.region] || doc.region)
283	      }
284	      return {
285	        _id: doc.id,
286	        id: doc.id,
287	        year: doc.year,
288	        yearDisplay: doc.yearDisplay,
289	        region: regionMap[doc.region] || doc.region,
290	        regionTag: doc.region,
291	        category: doc.category,
292	        title: displayTitle,
293	        keywords: null,
294	        cause: null,
295	        impact: null
296	      }
297	    }
298	
299	    global.historyData = null
300	    global.searchEngine = engine
301	  }
