303	  // 异步引擎初始化（带进度回调）
304	  function startEngineLoad() {
305	    if (engineInitialized) return
306	    engineInitialized = true
307	
308	    var engine = engineInstance
309	    var isQuickLaunch = global.quickLaunch || false
310	    global.addRuntimeLog('开始引擎初始化（' + (isQuickLaunch ? '快速启动' : '完整加载') + '）', 'info')
311	
312	    var onDone = function(success) {
313	      // 引擎就绪后再刷新一次，mapChunkSize / detailChunkSize 在 meta 加载后才准确
314	      mountToGlobal()
315	      if (success === true) {
316	        global.addRuntimeLog('引擎初始化完成', 'success')
317	      } else {
318	        global.addRuntimeLog('引擎初始化失败', 'error')
319	      }
320	    }
321	
322	    if (isQuickLaunch) {
323	      engine.initLight('/common/').then(onDone, onDone)
324	    } else {
325	      engine.init('/common/', function(percent, message) {
326	        if (typeof global.addRuntimeLog === 'function') {
327	          // 节流：只记录里程碑进度，避免刷屏
328	          if (percent % 10 === 0 || percent === 100) {
329	            global.addRuntimeLog('[引擎进度] ' + percent + '% ' + (message || ''), 'info')
330	          }
331	        }
332	      }).then(onDone, onDone)
333	    }
334	  }
