336	  // ========== 防抖锁 ==========
337	  export default {
338	    isNavigating: false,
339	
340	    safeNavigate(fn) {
341	      if (this.isNavigating) return
342	      this.isNavigating = true
343	      fn()
344	      setTimeout(() => { this.isNavigating = false }, 300)
345	    },
346	
347	    // ========== 全局初始化（onCreate 先于任何页面执行）==========
348	    onCreate() {
349	      global.addRuntimeLog('app.ux onCreate 应用创建', 'info')
350	
351	      // 1. 立即创建引擎并挂载全局接口
352	      //    即使引擎尚未就绪，global.searchHistory / global.getItemById /
353	      //    global.searchEngine 等也已定义，页面调用不会 undefined
354	      engineInstance = getSearchEngine()
355	      mountToGlobal()
356	
357	      // 2. 读取设置后启动引擎异步初始化（SearchEngine.init 读取 /common/ 下 map/detail 文件）
358	      loadSettingsAsync().then(function() {
359	        loadQuotes()
360	        startEngineLoad()
361	      })
362	    }
363	  }
